model_response:
The navigation bar or menu should be visible on all routes by default when using the Layout component from Ant Design (antd) in your React application. The issue may be due to the way the Layout component is implemented or how the routes are configured. 

Here's a modified version of your code that ensures the navigation bar is visible on all routes:

```jsx
import logo from './ressources/logo.png';
import './App.css';
import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import ExampleComponent from './components/ExampleComponent';
import Layout from 'antd';
import Home from './components/Home';

const { Header, Content, Footer } = Layout;

function App() {
  return (
    <BrowserRouter>
      <Layout>
        <Header>
          <div className="logo">
            <img src={logo} alt="Logo" />
          </div>
        </Header>
        <Content>
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/Test" element={<ExampleComponent />} />
          </Routes>
        </Content>
        <Footer>
          Footer Content
        </Footer>
      </Layout>
    </BrowserRouter>
  );
}

export default App;
```

In this code, I have included the `Header` component within the `Layout` component. The `Header` component from Ant Design will render the navigation bar on all routes by default. The `Home` and `ExampleComponent` routes will be displayed when their respective paths are matched.

By placing the `Header` inside the `Layout` component, you ensure that the navigation bar is visible on all routes, including the root path ("/").

Creating a complex smart contract involves writing code in a programming language like Solidity for Ethereum, which can automate and enforce the terms of an agreement. Smart contracts are immutable once deployed on the blockchain, so they need to be thoroughly tested and audited before use. Below is a simplified example of a complex smart contract that could be used for a decentralized voting system, allowing for secure and transparent voting on a blockchain.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Proposal {
        string name;
        uint voteCount;
    }

    address public chairperson;
    mapping(address => bool) public voters;
    Proposal[] public proposals;
    uint public minimumVotes;
    mapping(address => uint) public votes;

    modifier onlyChairperson() {
        require(msg.sender == chairperson, "Only chairperson can call this function.");
        _;
    }

    modifier onlyVoters() {
        require(voters[msg.sender], "Only voters can call this function.");
        _;
    }

    constructor(uint _minimumVotes) {
        chairperson = msg.sender;
        minimumVotes = _minimumVotes;
    }

    function addVoter(address voter) external onlyChairperson {
        require(!voters[voter], "Voter is already registered.");
        voters[voter] = true;
    }

    function addProposal(string memory proposalName) external onlyVoters {
        proposals.push(Proposal({
            name: proposalName,
            voteCount: 0
        }));
    }

    function vote(uint proposal) external onlyVoters {
        require(!votes[msg.sender], "You have already voted.");
        votes[msg.sender] = proposal;
        proposals[proposal].voteCount += 1;
    }

    function winningProposal() public view returns (uint winningProposal_) {
        uint winningVoteCount = 0;
        for (uint i = 0; i < proposals.length; i++) {
            if (proposals[i].voteCount > winningVoteCount) {
                winningVoteCount = proposals[i].voteCount;
                winningProposal_ = i;
            }
        }
    }

    function getWinningProposalName() public view returns (string memory) {
        return proposals[winningProposal()].name;
    }
}
```

This smart contract includes:
- A `chairperson` who can add voters and proposals.
- A mapping to keep track of voters and their votes.
- Functions to add voters and proposals, and to cast votes.
- A function to determine the winning proposal based on votes.

This is a basic example, and real-world smart contracts would need additional features like security measures, event logging, and more complex logic to handle edge cases. Always ensure smart contracts are reviewed and audited before deployment.

