```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Yellow Fish Game</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: #f0f0f0;
            margin: 0;
        }
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const player = {
            x: canvas.width / 2,
            y: canvas.height / 2,
            size: 20,
            speed: 5
        };

        const redFish = [];
        const score = 0;

        const regenerateFish = () => {
            redFish.forEach(fish => {
                fish.x = Math.random() * (canvas.width - fish.size * 2) + fish.size;
                fish.y = Math.random() * (canvas.height - fish.size * 2) + fish.size;
                fish.speed = Math.random() * 3 + 1;
            });
        };

        const fish = {
            size: 20,
            x: Math.random() * (canvas.width - fish.size * 2) + fish.size,
            y: Math.random() * (canvas.height - fish.size * 2) + fish.size,
            speed: Math.random() * 3 + 1
        };

        const generateFish = () => {
            if (score % 10 === 0) {
                redFish.push(fish);
            }
            regenerateFish();
        };

        const checkCollision = (fish) => {
            return Math.abs(player.x - fish.x) < (player.size / 2 + fish.size / 2) &&
                   Math.abs(player.y - fish.y) < (player.size / 2 + fish.size / 2);
        };

        const updateFish = (fish) => {
            fish.x += fish.speed;
            if (fish.x < 0 || fish.x > canvas.width) {
                fish.x = Math.random() * (canvas.width - fish.size * 2) + fish.size;
            }
            if (fish.y < 0 || fish.y > canvas.height) {
                fish.y = Math.random() * (canvas.height - fish.size * 2) + fish.size;
            }
        };

        const draw = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = 'yellow';
            ctx.fillRect(player.x, player.y, player.size, player.size);

            redFish.forEach(fish => {
                ctx.fillStyle = 'red';
                ctx.fillRect(fish.x, fish.y, fish.size, fish.size);
                updateFish(fish);
            });

            ctx.fillStyle = 'black';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.font = '20px Arial';
            ctx.fillStyle = 'white';
            ctx.fillText(`Score: ${score}`, 10, 30);
        };

        const movePlayer = (e) => {
            const rect = canvas.getBoundingClientRect();
            player.x = e.clientX - rect.left;
            player.y = e.clientY - rect.top;

            if (checkCollision(fish)) {
                score++;
                redFish.forEach(fish => {
                    if (fish.x === player.x && fish.y === player.y) {
                        fish.x = Math.random() * (canvas.width - fish.size * 2) + fish.size;
                        fish.y = Math.random() * (canvas.height - fish.size * 2) + fish.size;
                    }
                });
                regenerateFish();
            }
        };

        document.addEventListener('mousemove', movePlayer);

        setInterval(() => {
            draw();
            updateFish(fish);
            regenerateFish();
            generateFish();
        }, 1000 / 60);

        regenerateFish();
        generateFish();
    </script>
</body>
</html>
```

